import { expect, test } from '@playwright/test'
import { EVIDENCE, LIVE } from '../src/content/pitch'
import { mockPutLabApi } from './fixtures/mock-api'

// The Pitch states a verdict and prints the study it rests on.
//
// What matters is that the verdict's counts are the JSON's counts: the page
// is regenerated by `make pitch-evidence`, and a sentence that kept saying
// "lost money in 11 of 12 rules" after the data said otherwise would be the
// exact failure this page exists to prevent. So every check below derives its
// expectation from content/pitch_evidence.json, never from a literal.

test.beforeEach(async ({ page }) => {
  await mockPutLabApi(page)
  await page.goto('/')
  await page.getByRole('tab', { name: 'Pitch' }).click()
})

test('leads with the verdict, built from the evidence file', async ({ page }) => {
  await expect(page.getByRole('heading', { level: 2 })).toHaveText('No demonstrable edge.')
  const spy = Object.values(EVIDENCE.SPY.standalone)
  const losing = spy.filter((s) => s.mean_roi < 0).length
  const verdict = page.getByTestId('pitch-verdict')
  await expect(verdict).toContainText(`lost money in ${losing} of ${spy.length} rules`)
  // Counted per rule, not per book: a rule's three budgets share its rolls.
  const cfg = EVIDENCE.SPY.hedge.configs
  const rules = [...new Set(cfg.map((c) => c.rule))]
  const alwaysLose = rules.filter((r) => cfg.filter((c) => c.rule === r).every((c) => c.edge <= 0)).length
  await expect(verdict).toContainText(`${alwaysLose} of ${rules.length} rules lowered long-run growth at every budget`)
  await expect(verdict).toContainText(
    `of ${EVIDENCE.timing.bh.tested} rule-and-filter combinations tested for timing, ${EVIDENCE.timing.bh.survivors.length} survived`,
  )
  await expect(verdict).toContainText('does not produce a daily trading signal')
})

test('the verdict list prints the counts the evidence gives', async ({ page }) => {
  // Each sentence once printed a wrong count ("for 12 the whole interval sits
  // below zero", "31 of them at a cost in growth"); derive and pin them.
  const spy = Object.values(EVIDENCE.SPY.standalone)
  const below = spy.filter((s) => s.mean_roi_ci95[1]! < 0).length
  const h = EVIDENCE.SPY.hedge
  const cut = h.configs.filter((c) => c.max_dd > h.unhedged_max_dd)
  const cutAndLost = cut.filter((c) => c.edge <= 0).length
  const list = page.locator('#pitch-verdict-detail')
  await expect(list).toContainText(`for ${below} the whole 95% interval sits below zero`)
  await expect(list).toContainText(`${cut.length} of ${h.configs.length} SPY books cut the worst drawdown, ${cutAndLost} of them at a cost in growth`)
  const c08 = EVIDENCE.crisis_2008
  await expect(list).toContainText(`${c08.n_beat} of ${c08.configs} books ended ahead of unhedged`)
})

test('prints the 2008-09 check, one row per depth and budget', async ({ page }) => {
  const c08 = EVIDENCE.crisis_2008
  const rows = (['5pct', '10pct', '15pct', '20pct'] as const).reduce((n, k) => n + c08[k].books.length, 0)
  await expect(page.getByTestId('pitch-2008').locator('tbody tr')).toHaveCount(rows)
})

test('says which 2008-09 rolls the guards refused, and why', async ({ page }) => {
  // A deep put with no winners through Lehman reads as the market's verdict
  // unless the page says the quote guard refused the crash month.
  const section = page.locator('#pitch-2008')
  for (const k of ['5pct', '10pct', '15pct', '20pct'] as const) {
    for (const r of EVIDENCE.crisis_2008[k].refused) await expect(section).toContainText(`${r.entry}: ${r.reason}`)
  }
})

test('compares Cboe total-return indices with the index plus dividends', async ({ page }) => {
  const yardstick = EVIDENCE.cboe.SPX.growth + EVIDENCE.dividend_yield_assumed
  const pctText = (x: number) => `${x < 0 ? '−' : '+'}${Math.abs(x * 100).toFixed(2)}%`
  await expect(page.locator('#pitch-hedge')).toContainText(`${pctText(yardstick)} a year`)
})

test('names the commit that generated the evidence', async ({ page }) => {
  expect(EVIDENCE.code.dirty).toBe(false)
  await expect(page.getByTestId('pitch-code-sha')).toHaveText(EVIDENCE.code.sha.slice(0, 12))
  // The branch commit does not survive a squash merge; the tree hashes do.
  await expect(page.locator('#pitch-reproduce')).toContainText(EVIDENCE.code.tree.src.slice(0, 12))
})

test('the headline still fits the evidence it summarises', () => {
  // "No demonstrable edge" is a claim about the file: no standalone rule
  // whose whole interval is above zero, no timing filter surviving BH, and
  // every hedge that beat unhedged depending on one roll. If a regenerated
  // file breaks any of these, the headline must be rewritten, not kept.
  for (const s of Object.values(EVIDENCE.SPY.standalone)) expect(s.mean_roi_ci95[0]).toBeLessThanOrEqual(0)
  for (const s of Object.values(EVIDENCE.QQQ.standalone)) expect(s.mean_roi_ci95[0]).toBeLessThanOrEqual(0)
  expect(EVIDENCE.timing.bh.survivors.filter((s) => (s.oos.mean_roi_taken ?? 0) > 0)).toHaveLength(0)
  for (const c of [...EVIDENCE.SPY.hedge.configs, ...EVIDENCE.QQQ.hedge.configs]) {
    if (c.edge > 0) expect(c.drop_best?.edge_without_best).toBeLessThan(0)
  }
  // The p floor must sit under the first BH step, or "0 survived" is an
  // artefact of the bootstrap's draw count.
  expect(EVIDENCE.timing.bh.p_floor).toBeLessThan(EVIDENCE.timing.bh.fdr / EVIDENCE.timing.bh.tested)
})

test('prints one standalone row per rule and one hedge row per configuration', async ({ page }) => {
  await expect(page.getByTestId('pitch-standalone').locator('tbody tr')).toHaveCount(
    Object.keys(EVIDENCE.SPY.standalone).length,
  )
  await expect(page.getByTestId('pitch-hedge').locator('tbody tr')).toHaveCount(EVIDENCE.SPY.hedge.configs.length)
  await expect(page.getByTestId('pitch-bh')).toHaveText(String(EVIDENCE.timing.bh.survivors.length))
})

test('shows the dated live verdict flips it cites', async ({ page }) => {
  const rows = page.getByTestId('pitch-flips').locator('tbody tr')
  await expect(rows).toHaveCount(LIVE.spy_verdicts.length)
  await expect(rows.first()).toContainText(LIVE.spy_verdicts[0]!.as_of)
})

test('names the lake snapshots the study read', async ({ page }) => {
  for (const id of Object.values(EVIDENCE.snapshots)) {
    await expect(page.getByText(id, { exact: false }).first()).toBeVisible()
  }
})

test('does not scroll sideways at phone width', async ({ page }) => {
  await page.setViewportSize({ width: 375, height: 800 })
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth)
  expect(overflow).toBeLessThanOrEqual(0)
})

test('the data table shows what each dataset is without a sideways scroll on a phone', async ({ page }) => {
  // A long snapshot id once filled the screen and pushed "What it is" off it.
  await page.setViewportSize({ width: 390, height: 800 })
  const firstRow = page.getByTestId('pitch-data').locator('tbody tr').first()
  for (const col of [3, 4]) {
    const box = await firstRow.locator(`td:nth-child(${col})`).boundingBox()
    expect(box).not.toBeNull()
    expect(box!.x).toBeGreaterThanOrEqual(0)
    expect(box!.x + box!.width).toBeLessThanOrEqual(390)
  }
})

test('no 2008-09 refusal reason prints a quote', async ({ page }) => {
  // option_quotes is cleared for private research only and this page is
  // public: a reason names the guard, never a bid, ask or strike.
  const text = await page.locator('#pitch-2008').innerText()
  expect(text).not.toMatch(/\b(bid|ask|strike) \d/)
})

test('calls the smallest p-values one effect when they share their dates', async ({ page }) => {
  // Eight tests on the same entry dates skipping the same dates are one
  // result; the page once called them "a coherent effect" on every rule.
  const o = EVIDENCE.timing.bh.smallest_p_overlap
  const timing = page.locator('#pitch-timing')
  await expect(timing).not.toContainText('coherent')
  if (o.same_oos_entries && o.same_skipped) {
    await expect(timing).toContainText(`These are not ${o.tests} confirmations`)
    await expect(timing).toContainText(`skips the same ${o.skipped.length} of them`)
  }
})

test('explains each deeper drawdown by the put open on its peak day', async ({ page }) => {
  // A peak made of a put marked far above its cost is a paper gain given
  // back, not premium spent through a falling market; read it from the file.
  const h = EVIDENCE.SPY.hedge
  const paper = h.configs.filter((c) => c.max_dd < h.unhedged_max_dd && (c.max_dd_peak_put?.mark_multiple ?? 0) > 2)
  const section = page.locator('#pitch-hedge')
  for (const c of paper) await expect(section).toContainText(`marked ${c.max_dd_peak_put!.mark_multiple.toFixed(1)}× its cost on ${c.max_dd_span[0]}`)
  await expect(section).not.toContainText('premium spent through a falling market')
})

test('says how much of 2008-09 the spread guard decides', async ({ page }) => {
  const off = EVIDENCE.crisis_2008.spread_guard_off
  await expect(page.locator('#pitch-2008')).toContainText(
    `with it lifted, so a wide quote is bought at its ask, ${off.n_beat} of ${EVIDENCE.crisis_2008.configs} books end ahead`,
  )
})

test('on a phone the hedge table shows growth against unhedged without scrolling', async ({ page }) => {
  // The column the section is about once started off-screen at 390px.
  await page.setViewportSize({ width: 390, height: 800 })
  const cell = page.getByTestId('pitch-hedge').locator('tbody tr').first().locator('td:nth-child(2)')
  await expect(cell).toContainText('pp/yr')
  const box = await cell.boundingBox()
  expect(box!.x + box!.width).toBeLessThanOrEqual(390)
})
